-- Build the article matches, date histogram, and forward-return views for this search.
-- The seven-column stored-page contract is unchanged; counts are data driven.
-- Each query contributes one vote split across ALL tied highest RRF candidates.
-- No article text, vectors, result pairs or HTML are downloaded by the runner.

CREATE TEMP TABLE full2m_eval_report_history_v01 AS
SELECT
  c.document_id AS historical_document_id,
  c.title AS title,
  c.document_url AS document_url,
  c.observed_day AS observed_day,
  c.metadata_text AS metadata_text
FROM `${corpus_documents}` AS c
JOIN
  (SELECT DISTINCT m.historical_document_id AS historical_document_id
   FROM `${dataset}.full2m_eval_matches_v01` AS m) AS wanted ON wanted.historical_document_id=c.document_id;


CREATE TABLE `${dataset}.full2m_eval_report_pages_v01` CLUSTER BY
  report_name,
  page_number AS WITH
  cosine_top AS
  (SELECT
     m.query_document_id AS query_document_id,
     m.historical_document_id AS historical_document_id,
     m.cosine_distance AS score
   FROM `${dataset}.full2m_eval_matches_v01` AS m
   WHERE m.cosine_distance IS NOT NULL QUALIFY m.cosine_distance=MIN(m.cosine_distance) OVER (PARTITION BY m.query_document_id)),
  cosine_winners AS
  (SELECT
     t.query_document_id AS query_document_id,
     t.historical_document_id AS historical_document_id,
     t.score AS score,
     COUNT(*) OVER (PARTITION BY t.query_document_id) AS tie_count
   FROM cosine_top AS t QUALIFY ROW_NUMBER() OVER (PARTITION BY t.query_document_id
                                                   ORDER BY t.historical_document_id)=1),
  bm25_top AS
  (SELECT
     m.query_document_id AS query_document_id,
     m.historical_document_id AS historical_document_id,
     m.bm25_score_exact AS score
   FROM `${dataset}.full2m_eval_matches_v01` AS m
   WHERE m.bm25_score_exact IS NOT NULL
     AND m.bm25_score_exact>0 QUALIFY m.bm25_score_exact=MAX(m.bm25_score_exact) OVER (PARTITION BY m.query_document_id)),
  bm25_winners AS
  (SELECT
     t.query_document_id AS query_document_id,
     t.historical_document_id AS historical_document_id,
     t.score AS score,
     COUNT(*) OVER (PARTITION BY t.query_document_id) AS tie_count
   FROM bm25_top AS t QUALIFY ROW_NUMBER() OVER (PARTITION BY t.query_document_id
                                                 ORDER BY t.historical_document_id)=1),
  fused_top AS
  (SELECT
     m.query_document_id AS query_document_id,
     m.historical_document_id AS historical_document_id,
     m.rrf_score AS score
   FROM `${dataset}.full2m_eval_matches_v01` AS m
   WHERE m.rrf_score IS NOT NULL
     AND m.rrf_score>0 QUALIFY m.rrf_score=MAX(m.rrf_score) OVER (PARTITION BY m.query_document_id)),
  fused_winners AS
  (SELECT
     t.query_document_id AS query_document_id,
     t.historical_document_id AS historical_document_id,
     t.score AS score,
     COUNT(*) OVER (PARTITION BY t.query_document_id) AS tie_count
   FROM fused_top AS t QUALIFY ROW_NUMBER() OVER (PARTITION BY t.query_document_id
                                                  ORDER BY t.historical_document_id)=1),
  ordered_queries AS
  (SELECT
     q.*,
     ROW_NUMBER() OVER(
                       ORDER BY q.query_rank, q.query_document_id) AS display_rank
   FROM `${query_documents}` AS q),
  cohort_summary AS
  (SELECT
     COUNT(*) AS query_documents,
     DIV(COUNT(*)+19, 20) AS page_count,

     (SELECT COUNT(*)
      FROM `${dense_documents}`) AS historical_documents
   FROM `${query_documents}`),
  case_pages AS
  (SELECT
     DIV(q.display_rank-1, 20)+1 AS page_number,
     ARRAY_AGG(STRUCT(q.display_rank AS query_rank, q.query_rank AS source_query_rank, STRUCT(q.query_document_id AS document_id, SUBSTR(q.title, 1, 400) AS title, IF(BYTE_LENGTH(q.document_url)<=8192, q.document_url, NULL) AS document_url, q.observed_day AS observed_day, q.metadata_text AS metadata_text) AS query, STRUCT(ch.historical_document_id AS document_id, SUBSTR(ch.title, 1, 400) AS title, IF(BYTE_LENGTH(ch.document_url)<=8192, ch.document_url, NULL) AS document_url, ch.observed_day AS observed_day, ch.metadata_text AS metadata_text, 1.0-cw.score AS score, cw.tie_count AS tie_count) AS cosine, STRUCT(bh.historical_document_id AS document_id, SUBSTR(bh.title, 1, 400) AS title, IF(BYTE_LENGTH(bh.document_url)<=8192, bh.document_url, NULL) AS document_url, bh.observed_day AS observed_day, bh.metadata_text AS metadata_text, CAST(bw.score AS FLOAT64) AS score, bw.tie_count AS tie_count) AS bm25, STRUCT(fh.historical_document_id AS document_id, SUBSTR(fh.title, 1, 400) AS title, IF(BYTE_LENGTH(fh.document_url)<=8192, fh.document_url, NULL) AS document_url, fh.observed_day AS observed_day, fh.metadata_text AS metadata_text, fw.score AS score, fw.tie_count AS tie_count) AS fused)
               ORDER BY q.display_rank) AS cases
   FROM ordered_queries AS q
   LEFT JOIN cosine_winners AS cw ON cw.query_document_id=q.query_document_id
   LEFT JOIN `full2m_eval_report_history_v01` AS ch ON ch.historical_document_id=cw.historical_document_id
   LEFT JOIN bm25_winners AS bw ON bw.query_document_id=q.query_document_id
   LEFT JOIN `full2m_eval_report_history_v01` AS bh ON bh.historical_document_id=bw.historical_document_id
   LEFT JOIN fused_winners AS fw ON fw.query_document_id=q.query_document_id
   LEFT JOIN `full2m_eval_report_history_v01` AS fh ON fh.historical_document_id=fw.historical_document_id
   GROUP BY page_number),
  weighted_winners AS
  (SELECT
     f.query_document_id AS query_document_id,
     f.historical_document_id AS historical_document_id,
     SAFE_DIVIDE(1.0, COUNT(*) OVER (PARTITION BY f.query_document_id)) AS vote
   FROM fused_top AS f),
  date_votes AS
  (SELECT
     h.observed_day AS observed_day,
     SUM(w.vote) AS votes,
     COUNT(DISTINCT w.historical_document_id) AS distinct_historical_documents
   FROM weighted_winners AS w
   JOIN `full2m_eval_report_history_v01` AS h ON h.historical_document_id=w.historical_document_id
   GROUP BY h.observed_day),
  date_rows AS
  (SELECT
     v.observed_day AS observed_day,
     v.votes AS votes,
     v.distinct_historical_documents AS distinct_historical_documents,
     m.anchor_date AS anchor_date,
     m.day20_date AS day20_date,
     m.forward_path AS forward_path
   FROM date_votes AS v
   JOIN `${market_paths}` AS m ON m.observed_day=v.observed_day
   AND m.eligible
   AND m.price_observations=21),
  weighted_path AS
  (SELECT
     p.horizon_sessions AS horizon_sessions,
     SAFE_DIVIDE(SUM(d.votes*p.price_return), SUM(d.votes)) AS weighted_price_return,
     SUM(d.votes) AS included_vote_weight,
     COUNT(*) AS historical_date_count
   FROM date_rows AS d
   CROSS JOIN UNNEST(d.forward_path) AS p
   GROUP BY p.horizon_sessions),
  vote_summary AS
  (SELECT
     COUNT(DISTINCT w.query_document_id) AS voted_queries,
     COUNT(DISTINCT w.historical_document_id) AS unique_matched_articles,
     SUM(w.vote) AS total_votes
   FROM weighted_winners AS w),
  date_summary AS
  (SELECT
     COUNT(DISTINCT d.anchor_date) AS unique_market_anchors,
     ARRAY_AGG(STRUCT(d.observed_day AS observed_day, d.votes AS votes, d.distinct_historical_documents AS distinct_historical_documents, d.anchor_date AS anchor_date, d.day20_date AS day20_date, ARRAY
                        (SELECT ROUND(x.price_return, 10)
                         FROM UNNEST(d.forward_path) AS x
                         ORDER BY x.horizon_sessions) AS forward_returns)
               ORDER BY d.observed_day) AS date_rows
   FROM date_rows AS d),
  path_summary AS
  (SELECT ARRAY_AGG(STRUCT(p.horizon_sessions AS horizon_sessions, p.weighted_price_return AS weighted_price_return, p.included_vote_weight AS included_vote_weight, p.historical_date_count AS historical_date_count)
                    ORDER BY p.horizon_sessions) AS weighted_path
   FROM weighted_path AS p),
  payloads AS
  (SELECT
     'best_matches' AS report_name,
     c.page_number AS page_number,
     TO_JSON_STRING(STRUCT(@run_id AS run_id,
                             (SELECT query_documents
                              FROM cohort_summary) AS query_documents,
                             (SELECT historical_documents
                              FROM cohort_summary) AS historical_documents,
                             (SELECT page_count
                              FROM cohort_summary) AS page_count, c.page_number AS page_number, PARSE_JSON(@report_context_json) AS context, c.cases AS cases)) AS payload_json
   FROM case_pages AS c
   UNION ALL BY NAME SELECT
     'dates_and_market' AS report_name,
     1 AS page_number,
     TO_JSON_STRING(STRUCT(@run_id AS run_id,
                             (SELECT query_documents
                              FROM cohort_summary) AS query_documents,
                             (SELECT historical_documents
                              FROM cohort_summary) AS historical_documents,
                             (SELECT page_count
                              FROM cohort_summary) AS page_count, 1 AS page_number, PARSE_JSON(@report_context_json) AS context, v.voted_queries AS voted_queries, v.unique_matched_articles AS unique_matched_articles, v.total_votes AS total_votes, d.unique_market_anchors AS unique_market_anchors, d.date_rows AS date_rows, p.weighted_path AS weighted_path)) AS payload_json
   FROM vote_summary AS v
   CROSS JOIN date_summary AS d
   CROSS JOIN path_summary AS p
   UNION ALL BY NAME SELECT
     'performance' AS report_name,
     1 AS page_number,
     TO_JSON_STRING(STRUCT(@run_id AS run_id,
                             (SELECT query_documents
                              FROM cohort_summary) AS query_documents,
                             (SELECT historical_documents
                              FROM cohort_summary) AS historical_documents,
                             (SELECT page_count
                              FROM cohort_summary) AS page_count, 1 AS page_number, PARSE_JSON(@report_context_json) AS context, PARSE_JSON(@performance_json) AS performance)) AS payload_json),
  rendered AS
  (SELECT
     p.report_name AS report_name,
     p.page_number AS page_number,
     CASE
         WHEN p.report_name='best_matches' THEN CONCAT('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Original articles and three best matches</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#172e43;font:16px/1.5 system-ui,-apple-system,sans-serif}header{background:#15394c;color:#fff;padding:30px max(20px,calc((100% - 1240px)/2))}header h1{font-size:30px;line-height:1.2;margin:4px 0 14px}header p{margin:4px 0;color:#d3e5eb}header small{color:#d3e5eb}nav{display:flex;gap:20px;flex-wrap:wrap;padding-top:17px}nav a{color:#fff;text-underline-offset:5px}main{max-width:1280px;margin:auto;padding:24px}section,.case{background:#fff;padding:22px;border:1px solid #d7e0e6;border-radius:9px;margin:0 0 22px}h2{font-size:23px;margin-top:0}h3{font-size:18px}a{color:#006888;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.55 ui-monospace,monospace}code{overflow-wrap:anywhere}.muted,small{color:#526b7b}.note{border-left:4px solid #c48b29;background:#fff7e7;padding:13px 16px}.cards,.winners{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.metric,.winner{background:#edf4f7;padding:16px;border-radius:6px}.metric strong{display:block;font-size:27px;margin-top:3px}.winner h3{margin:0 0 12px}.source{border-bottom:1px solid #d7e0e6;padding-bottom:15px;margin-bottom:17px}.score{font-variant-numeric:tabular-nums;font-weight:650}summary{cursor:pointer}details{margin-top:14px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:10px;border-bottom:1px solid #d7e0e6;text-align:left;vertical-align:top}th{background:#edf4f7}.scroll{overflow:auto;max-height:650px}.hist{display:grid;grid-template-columns:115px 1fr 80px;gap:12px;align-items:center;margin:4px 0}.bar{height:20px;min-width:1px;background:#197a91}.hist small{text-align:right}.pager{display:flex;justify-content:space-between;align-items:center;gap:15px}.button{display:inline-block;padding:8px 14px;border:1px solid #9aafbd;border-radius:5px;text-decoration:none;background:white}.chart svg{width:100%;height:auto;max-height:350px}select{font:inherit;padding:8px;max-width:100%;margin:7px 0}svg text{fill:#425d6e;font:12px system-ui}.stage{display:grid;grid-template-columns:minmax(180px,38%) 1fr 85px;gap:10px;align-items:center;padding:6px 0}.stage code{font-size:12px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.12em}.badge{display:inline-block;background:#dcecf0;padding:3px 8px;border-radius:4px;font-size:12px}@media(max-width:850px){.cards,.winners{grid-template-columns:1fr}main{padding:12px}header h1{font-size:26px}.stage{grid-template-columns:45% 1fr 55px}.hist{grid-template-columns:100px 1fr 60px}.case,section{padding:16px}}</style></head><body><header><div class="eyebrow">GKG article metadata · saved-cohort evaluation</div><h1>Original articles and three best matches</h1><p id="context"></p><p><small id="run"></small></p><nav><a href="/best-matches?page=1">Three-way matches</a><a href="/market">Dates and market paths</a><a href="/performance">Performance</a></nav></header><main><section><h2>Three retrieval choices for each original article</h2><div class="cards" id="cards"></div><p class="note">These are GKG metadata comparisons. Cosine uses approximate search over the selected historical corpus, searching 40% of the IVF lists. BM25 searches the same eligible historical documents with stable decimal score accumulation. Combined rank uses reciprocal rank fusion with k = 60; it is not a probability or a model judgment. The cosine winner is the best returned approximate candidate. Equal best scores use a stable document-ID representative for display; tie counts are shown for the retained candidate set.</p><div class="pager" id="pager-top"></div></section><div id="cases"></div><section><div class="pager" id="pager-bottom"></div></section></main><script id="report-data" type="application/json">', REPLACE(p.payload_json, '<', r'\u003c'), '</script><script>const D=JSON.parse(document.getElementById(\'report-data\').textContent),el=id=>document.getElementById(id);const esc=x=>String(x??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));const num=x=>typeof x===\'number\'&&Number.isFinite(x)?x.toLocaleString(undefined,{maximumFractionDigits:6}):\'Unavailable\';const pct=x=>typeof x===\'number\'&&Number.isFinite(x)?(100*x).toFixed(3)+\'%\':\'Unavailable\';function cards(items){return items.map(([label,value])=>\'<div class="metric">\'+esc(label)+\'<strong>\'+esc(value)+\'</strong></div>\').join(\'\')}function url(u){if(typeof u!==\'string\'||!u)return \'<span class="muted">URL unavailable in this display.</span>\';try{const v=new URL(u);if([\'http:\',\'https:\'].includes(v.protocol))return \'<a href="\'+esc(u)+\'" target="_blank" rel="noopener noreferrer">\'+esc(u)+\'</a>\'}catch{}return \'<span>\'+esc(u)+\'</span>\'}function documentHTML(d){if(!d||!d.document_id)return \'<p>No qualifying result in this channel.</p>\';return \'<p><strong>\'+esc(d.title||\'GKG metadata document\')+\'</strong></p><p class="muted">GKG observation \'+esc(d.observed_day||\'unavailable\')+\'</p><p>\'+url(d.document_url)+\'</p><details><summary>Metadata and document identity</summary><p><code>\'+esc(d.document_id)+\'</code></p><pre>\'+esc(d.metadata_text||\'No metadata text\')+\'</pre></details>\'}function chart(path,key){if(!Array.isArray(path)||!path.length)return \'<p>Complete market path unavailable.</p>\';const values=path.filter(p=>Number.isFinite(p[key]));if(!values.length)return \'<p>Complete market path unavailable.</p>\';let lo=Math.min(0,...values.map(p=>p[key])),hi=Math.max(0,...values.map(p=>p[key]));if(hi-lo<.002){lo-=.001;hi+=.001}const W=850,H=300,L=80,R=18,T=18,B=46,x=h=>L+h/20*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let out=\'<svg viewBox="0 0 \'+W+\' \'+H+\'" role="img" aria-label="Cumulative historical price returns over twenty trading sessions">\';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;out+=\'<line x1="\'+L+\'" x2="\'+(W-R)+\'" y1="\'+y(v)+\'" y2="\'+y(v)+\'" stroke="#d7e0e6"/><text x="\'+(L-8)+\'" y="\'+(y(v)+4)+\'" text-anchor="end">\'+pct(v)+\'</text>\'}let segments=[],segment=[];for(const p of path){if(Number.isFinite(p[key]))segment.push(p);else if(segment.length){segments.push(segment);segment=[]}}if(segment.length)segments.push(segment);for(const segment of segments)out+=\'<polyline fill="none" stroke="#197a91" stroke-width="3" points="\'+segment.map(p=>x(p.horizon_sessions)+\',\'+y(p[key])).join(\' \')+\'"/>\';for(const h of [0,5,10,15,20])out+=\'<text x="\'+x(h)+\'" y="\'+(H-24)+\'" text-anchor="middle">\'+h+\'</text>\';return out+\'<text x="\'+W/2+\'" y="\'+(H-4)+\'" text-anchor="middle">Trading sessions after entry close</text></svg>\'}el(\'run\').textContent=D.run_id;el(\'context\').textContent=\'Historical corpus: \'+num(D.historical_documents)+\' article identities. Reused saved query cohort: \'+num(D.query_documents)+\'. Article bodies were not fetched.\';el(\'cards\').innerHTML=cards([[\'Saved articles in cohort\',D.query_documents],[\'This page\',D.page_number+\' / \'+D.page_count],[\'Articles on this page\',D.cases.length]]);function winner(label,w,metric){if(!w||!w.document_id)return \'<article class="winner"><h3>\'+esc(label)+\'</h3><p>No qualifying result in this channel.</p></article>\';return \'<article class="winner"><h3>\'+esc(label)+\'</h3><p class="score">\'+esc(metric)+\': \'+num(w.score)+\'</p><p class="muted">\'+num(w.tie_count)+\' tied best candidate(s)</p>\'+documentHTML(w)+\'</article>\'}el(\'cases\').innerHTML=D.cases.map(c=>\'<article class="case"><div class="source"><span class="badge">Original article \'+num(c.query_rank)+\' of \'+num(D.query_documents)+\'</span>\'+documentHTML(c.query)+\'</div><div class="winners">\'+winner(\'Best cosine\',c.cosine,\'Cosine similarity\')+winner(\'Best BM25\',c.bm25,\'BM25\')+winner(\'Best combined\',c.fused,\'RRF score\')+\'</div></article>\').join(\'\');let navigation=(D.page_number>1?\'<a class="button" href="/best-matches?page=\'+(D.page_number-1)+\'">Previous 20</a>\':\'<span></span>\')+\'<span>Page \'+D.page_number+\' of \'+D.page_count+\'</span>\'+(D.page_number<D.page_count?\'<a class="button" href="/best-matches?page=\'+(D.page_number+1)+\'">Next 20</a>\':\'<span></span>\');el(\'pager-top\').innerHTML=navigation;el(\'pager-bottom\').innerHTML=navigation;</script></body></html>')
         WHEN p.report_name='dates_and_market' THEN CONCAT('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Historical-date histogram and market paths</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#172e43;font:16px/1.5 system-ui,-apple-system,sans-serif}header{background:#15394c;color:#fff;padding:30px max(20px,calc((100% - 1240px)/2))}header h1{font-size:30px;line-height:1.2;margin:4px 0 14px}header p{margin:4px 0;color:#d3e5eb}header small{color:#d3e5eb}nav{display:flex;gap:20px;flex-wrap:wrap;padding-top:17px}nav a{color:#fff;text-underline-offset:5px}main{max-width:1280px;margin:auto;padding:24px}section,.case{background:#fff;padding:22px;border:1px solid #d7e0e6;border-radius:9px;margin:0 0 22px}h2{font-size:23px;margin-top:0}h3{font-size:18px}a{color:#006888;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.55 ui-monospace,monospace}code{overflow-wrap:anywhere}.muted,small{color:#526b7b}.note{border-left:4px solid #c48b29;background:#fff7e7;padding:13px 16px}.cards,.winners{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.metric,.winner{background:#edf4f7;padding:16px;border-radius:6px}.metric strong{display:block;font-size:27px;margin-top:3px}.winner h3{margin:0 0 12px}.source{border-bottom:1px solid #d7e0e6;padding-bottom:15px;margin-bottom:17px}.score{font-variant-numeric:tabular-nums;font-weight:650}summary{cursor:pointer}details{margin-top:14px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:10px;border-bottom:1px solid #d7e0e6;text-align:left;vertical-align:top}th{background:#edf4f7}.scroll{overflow:auto;max-height:650px}.hist{display:grid;grid-template-columns:115px 1fr 80px;gap:12px;align-items:center;margin:4px 0}.bar{height:20px;min-width:1px;background:#197a91}.hist small{text-align:right}.pager{display:flex;justify-content:space-between;align-items:center;gap:15px}.button{display:inline-block;padding:8px 14px;border:1px solid #9aafbd;border-radius:5px;text-decoration:none;background:white}.chart svg{width:100%;height:auto;max-height:350px}select{font:inherit;padding:8px;max-width:100%;margin:7px 0}svg text{fill:#425d6e;font:12px system-ui}.stage{display:grid;grid-template-columns:minmax(180px,38%) 1fr 85px;gap:10px;align-items:center;padding:6px 0}.stage code{font-size:12px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.12em}.badge{display:inline-block;background:#dcecf0;padding:3px 8px;border-radius:4px;font-size:12px}@media(max-width:850px){.cards,.winners{grid-template-columns:1fr}main{padding:12px}header h1{font-size:26px}.stage{grid-template-columns:45% 1fr 55px}.hist{grid-template-columns:100px 1fr 60px}.case,section{padding:16px}}</style></head><body><header><div class="eyebrow">GKG article metadata · saved-cohort evaluation</div><h1>Historical-date histogram and market paths</h1><p id="context"></p><p><small id="run"></small></p><nav><a href="/best-matches?page=1">Three-way matches</a><a href="/market">Dates and market paths</a><a href="/performance">Performance</a></nav></header><main><section><h2>Historical dates selected by the combined match</h2><div class="cards" id="cards"></div><p class="note">Historical matches were eligible before retrieval only when all twenty subsequent trading-session closes were present. Dates are GKG observation dates, not verified publication dates. Multiple article matches can refer to the same date and the same market path.</p><p id="date-policy"></p><div class="scroll" id="histogram"></div></section><section><h2>Market path for a selected historical date</h2><label for="historical-date">GKG observation date</label><br><select id="historical-date"></select><p id="anchor"></p><div class="chart" id="individual"></div></section><section><h2>Vote-weighted average forward path</h2><p>Each query contributes one vote. If its highest combined score is tied, that vote is split equally across all tied best candidates retained in the matching results. Date votes add those fractions. At each horizon h, the displayed average is sum(date votes × date return at h) / sum(included date votes). Similarity scores are not treated as weights.</p><div class="chart" id="weighted"></div><div class="cards" id="returns"></div><p id="concentration"></p><p class="note">These are descriptive historical price returns, with dividends excluded. The average is not a forecast, a causal estimate, or a set of independent market outcomes. The entry close is the first trading-session close strictly after the GKG observation date; horizons 0 through 20 use that entry as their base.</p><div class="scroll" id="weights"></div></section></main><script id="report-data" type="application/json">', REPLACE(p.payload_json, '<', r'\u003c'), '</script><script>const D=JSON.parse(document.getElementById(\'report-data\').textContent),el=id=>document.getElementById(id);const esc=x=>String(x??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));const num=x=>typeof x===\'number\'&&Number.isFinite(x)?x.toLocaleString(undefined,{maximumFractionDigits:6}):\'Unavailable\';const pct=x=>typeof x===\'number\'&&Number.isFinite(x)?(100*x).toFixed(3)+\'%\':\'Unavailable\';function cards(items){return items.map(([label,value])=>\'<div class="metric">\'+esc(label)+\'<strong>\'+esc(value)+\'</strong></div>\').join(\'\')}function url(u){if(typeof u!==\'string\'||!u)return \'<span class="muted">URL unavailable in this display.</span>\';try{const v=new URL(u);if([\'http:\',\'https:\'].includes(v.protocol))return \'<a href="\'+esc(u)+\'" target="_blank" rel="noopener noreferrer">\'+esc(u)+\'</a>\'}catch{}return \'<span>\'+esc(u)+\'</span>\'}function documentHTML(d){if(!d||!d.document_id)return \'<p>No qualifying result in this channel.</p>\';return \'<p><strong>\'+esc(d.title||\'GKG metadata document\')+\'</strong></p><p class="muted">GKG observation \'+esc(d.observed_day||\'unavailable\')+\'</p><p>\'+url(d.document_url)+\'</p><details><summary>Metadata and document identity</summary><p><code>\'+esc(d.document_id)+\'</code></p><pre>\'+esc(d.metadata_text||\'No metadata text\')+\'</pre></details>\'}function chart(path,key){if(!Array.isArray(path)||!path.length)return \'<p>Complete market path unavailable.</p>\';const values=path.filter(p=>Number.isFinite(p[key]));if(!values.length)return \'<p>Complete market path unavailable.</p>\';let lo=Math.min(0,...values.map(p=>p[key])),hi=Math.max(0,...values.map(p=>p[key]));if(hi-lo<.002){lo-=.001;hi+=.001}const W=850,H=300,L=80,R=18,T=18,B=46,x=h=>L+h/20*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let out=\'<svg viewBox="0 0 \'+W+\' \'+H+\'" role="img" aria-label="Cumulative historical price returns over twenty trading sessions">\';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;out+=\'<line x1="\'+L+\'" x2="\'+(W-R)+\'" y1="\'+y(v)+\'" y2="\'+y(v)+\'" stroke="#d7e0e6"/><text x="\'+(L-8)+\'" y="\'+(y(v)+4)+\'" text-anchor="end">\'+pct(v)+\'</text>\'}let segments=[],segment=[];for(const p of path){if(Number.isFinite(p[key]))segment.push(p);else if(segment.length){segments.push(segment);segment=[]}}if(segment.length)segments.push(segment);for(const segment of segments)out+=\'<polyline fill="none" stroke="#197a91" stroke-width="3" points="\'+segment.map(p=>x(p.horizon_sessions)+\',\'+y(p[key])).join(\' \')+\'"/>\';for(const h of [0,5,10,15,20])out+=\'<text x="\'+x(h)+\'" y="\'+(H-24)+\'" text-anchor="middle">\'+h+\'</text>\';return out+\'<text x="\'+W/2+\'" y="\'+(H-4)+\'" text-anchor="middle">Trading sessions after entry close</text></svg>\'}el(\'run\').textContent=D.run_id;el(\'context\').textContent=\'Historical corpus: \'+num(D.historical_documents)+\' article identities. Reused saved query cohort: \'+num(D.query_documents)+\'. Article bodies were not fetched.\';el(\'cards\').innerHTML=cards([[\'Queries contributing votes\',D.voted_queries],[\'Historical dates selected\',D.date_rows.length],[\'Distinct entry-date paths\',D.unique_market_anchors]]);el(\'date-policy\').textContent=\'Total vote weight \'+num(D.total_votes)+\'; distinct matched historical article identities \'+num(D.unique_matched_articles)+\'. Frozen market as-of: \'+(D.context?.market_as_of_utc||\'see the retained market contract\')+\'.\';const largest=Math.max(1,...D.date_rows.map(r=>r.votes));el(\'histogram\').innerHTML=D.date_rows.map(r=>\'<div class="hist"><span>\'+esc(r.observed_day)+\'</span><span class="bar" style="width:\'+100*r.votes/largest+\'%"></span><small>\'+num(r.votes)+\'</small></div>\').join(\'\');el(\'historical-date\').innerHTML=D.date_rows.map(r=>\'<option value="\'+esc(r.observed_day)+\'">\'+esc(r.observed_day)+\' — \'+num(r.votes)+\' votes</option>\').join(\'\');function drawDate(){const r=D.date_rows.find(x=>x.observed_day===el(\'historical-date\').value);el(\'anchor\').textContent=r?\'Entry close \'+r.anchor_date+\'; twentieth subsequent session \'+r.day20_date+\'. \'+num(r.votes)+\' query votes.\':\'No complete date path.\';el(\'individual\').innerHTML=chart(r?.forward_returns?.map((value,index)=>({horizon_sessions:index,price_return:value})),\'price_return\')}el(\'historical-date\').onchange=drawDate;drawDate();el(\'weighted\').innerHTML=chart(D.weighted_path,\'weighted_price_return\');function at(h){return D.weighted_path.find(p=>p.horizon_sessions===h)?.weighted_price_return}el(\'returns\').innerHTML=cards([[\'5-session average\',pct(at(5))],[\'10-session average\',pct(at(10))],[\'20-session average\',pct(at(20))]]);const maxShare=Math.max(0,...D.date_rows.map(r=>r.votes))/D.total_votes;el(\'concentration\').textContent=\'Largest historical-date vote share: \'+pct(maxShare)+\'. \'+num(D.unique_market_anchors)+\' distinct entry-date paths underlie \'+num(D.total_votes)+\' votes. All included paths contain 21 observed closes (entry plus 20 sessions).\';el(\'weights\').innerHTML=\'<table><thead><tr><th>GKG date</th><th>Entry close</th><th>Votes</th><th>Weight</th><th>Matched article identities</th><th>20-session return</th></tr></thead><tbody>\'+D.date_rows.map(r=>\'<tr><td>\'+esc(r.observed_day)+\'</td><td>\'+esc(r.anchor_date)+\'</td><td>\'+num(r.votes)+\'</td><td>\'+pct(r.votes/D.total_votes)+\'</td><td>\'+num(r.distinct_historical_documents)+\'</td><td>\'+pct(r.forward_returns?.[20])+\'</td></tr>\').join(\'\')+\'</tbody></table>\';</script></body></html>')
         WHEN p.report_name='performance' THEN CONCAT('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pipeline timing and bottlenecks</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#172e43;font:16px/1.5 system-ui,-apple-system,sans-serif}header{background:#15394c;color:#fff;padding:30px max(20px,calc((100% - 1240px)/2))}header h1{font-size:30px;line-height:1.2;margin:4px 0 14px}header p{margin:4px 0;color:#d3e5eb}header small{color:#d3e5eb}nav{display:flex;gap:20px;flex-wrap:wrap;padding-top:17px}nav a{color:#fff;text-underline-offset:5px}main{max-width:1280px;margin:auto;padding:24px}section,.case{background:#fff;padding:22px;border:1px solid #d7e0e6;border-radius:9px;margin:0 0 22px}h2{font-size:23px;margin-top:0}h3{font-size:18px}a{color:#006888;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:13px/1.55 ui-monospace,monospace}code{overflow-wrap:anywhere}.muted,small{color:#526b7b}.note{border-left:4px solid #c48b29;background:#fff7e7;padding:13px 16px}.cards,.winners{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.metric,.winner{background:#edf4f7;padding:16px;border-radius:6px}.metric strong{display:block;font-size:27px;margin-top:3px}.winner h3{margin:0 0 12px}.source{border-bottom:1px solid #d7e0e6;padding-bottom:15px;margin-bottom:17px}.score{font-variant-numeric:tabular-nums;font-weight:650}summary{cursor:pointer}details{margin-top:14px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:10px;border-bottom:1px solid #d7e0e6;text-align:left;vertical-align:top}th{background:#edf4f7}.scroll{overflow:auto;max-height:650px}.hist{display:grid;grid-template-columns:115px 1fr 80px;gap:12px;align-items:center;margin:4px 0}.bar{height:20px;min-width:1px;background:#197a91}.hist small{text-align:right}.pager{display:flex;justify-content:space-between;align-items:center;gap:15px}.button{display:inline-block;padding:8px 14px;border:1px solid #9aafbd;border-radius:5px;text-decoration:none;background:white}.chart svg{width:100%;height:auto;max-height:350px}select{font:inherit;padding:8px;max-width:100%;margin:7px 0}svg text{fill:#425d6e;font:12px system-ui}.stage{display:grid;grid-template-columns:minmax(180px,38%) 1fr 85px;gap:10px;align-items:center;padding:6px 0}.stage code{font-size:12px}.eyebrow{text-transform:uppercase;font-size:12px;letter-spacing:.12em}.badge{display:inline-block;background:#dcecf0;padding:3px 8px;border-radius:4px;font-size:12px}@media(max-width:850px){.cards,.winners{grid-template-columns:1fr}main{padding:12px}header h1{font-size:26px}.stage{grid-template-columns:45% 1fr 55px}.hist{grid-template-columns:100px 1fr 60px}.case,section{padding:16px}}</style></head><body><header><div class="eyebrow">GKG article metadata · saved-cohort evaluation</div><h1>Pipeline timing and bottlenecks</h1><p id="context"></p><p><small id="run"></small></p><nav><a href="/best-matches?page=1">Three-way matches</a><a href="/market">Dates and market paths</a><a href="/performance">Performance</a></nav></header><main><section><h2>Timing and resource evidence</h2><div class="cards" id="cards"></div><p class="note">This is one controlled re-evaluation of the saved articles against the selected historical corpus. It reuses their existing embeddings. Its timings exclude fresh intake and new embedding generation, and do not establish sustained production capacity. The report uses the measured timing scope recorded below; report viewing is outside the pipeline benchmark.</p><p id="scope"></p><div id="stages"></div></section><section><h2>Retrieval quality against an exact reference</h2><div class="cards" id="quality-cards"></div><p id="quality-scope"></p><p id="index-evidence"></p><p class="muted">Recall measures retrieval agreement. It does not measure whether a news comparison is economically useful, and historical returns are not a forecast.</p></section><section><h2>Saved server-job timings</h2><div class="scroll" id="jobs"></div></section><section><h2>SQL statements inside the pipeline stages</h2><p id="child-summary"></p><p class="muted">These child statements explain the parent jobs above. Their resources are already part of the parent accounting and must not be added to the parent totals again. This list includes preparation and exact-reference work; the stage names show where each statement belongs.</p><div class="scroll" id="child-jobs"></div></section><section><h2>Accounting and limitations</h2><p id="capacity"></p><div id="accounting"></div><details><summary>Full measured performance record</summary><pre id="performance-json"></pre></details></section></main><script id="report-data" type="application/json">', REPLACE(p.payload_json, '<', r'\u003c'), '</script><script>const D=JSON.parse(document.getElementById(\'report-data\').textContent),el=id=>document.getElementById(id);const esc=x=>String(x??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));const num=x=>typeof x===\'number\'&&Number.isFinite(x)?x.toLocaleString(undefined,{maximumFractionDigits:6}):\'Unavailable\';const pct=x=>typeof x===\'number\'&&Number.isFinite(x)?(100*x).toFixed(3)+\'%\':\'Unavailable\';function cards(items){return items.map(([label,value])=>\'<div class="metric">\'+esc(label)+\'<strong>\'+esc(value)+\'</strong></div>\').join(\'\')}function url(u){if(typeof u!==\'string\'||!u)return \'<span class="muted">URL unavailable in this display.</span>\';try{const v=new URL(u);if([\'http:\',\'https:\'].includes(v.protocol))return \'<a href="\'+esc(u)+\'" target="_blank" rel="noopener noreferrer">\'+esc(u)+\'</a>\'}catch{}return \'<span>\'+esc(u)+\'</span>\'}function documentHTML(d){if(!d||!d.document_id)return \'<p>No qualifying result in this channel.</p>\';return \'<p><strong>\'+esc(d.title||\'GKG metadata document\')+\'</strong></p><p class="muted">GKG observation \'+esc(d.observed_day||\'unavailable\')+\'</p><p>\'+url(d.document_url)+\'</p><details><summary>Metadata and document identity</summary><p><code>\'+esc(d.document_id)+\'</code></p><pre>\'+esc(d.metadata_text||\'No metadata text\')+\'</pre></details>\'}function chart(path,key){if(!Array.isArray(path)||!path.length)return \'<p>Complete market path unavailable.</p>\';const values=path.filter(p=>Number.isFinite(p[key]));if(!values.length)return \'<p>Complete market path unavailable.</p>\';let lo=Math.min(0,...values.map(p=>p[key])),hi=Math.max(0,...values.map(p=>p[key]));if(hi-lo<.002){lo-=.001;hi+=.001}const W=850,H=300,L=80,R=18,T=18,B=46,x=h=>L+h/20*(W-L-R),y=v=>T+(hi-v)/(hi-lo)*(H-T-B);let out=\'<svg viewBox="0 0 \'+W+\' \'+H+\'" role="img" aria-label="Cumulative historical price returns over twenty trading sessions">\';for(let i=0;i<5;i++){const v=lo+(hi-lo)*i/4;out+=\'<line x1="\'+L+\'" x2="\'+(W-R)+\'" y1="\'+y(v)+\'" y2="\'+y(v)+\'" stroke="#d7e0e6"/><text x="\'+(L-8)+\'" y="\'+(y(v)+4)+\'" text-anchor="end">\'+pct(v)+\'</text>\'}let segments=[],segment=[];for(const p of path){if(Number.isFinite(p[key]))segment.push(p);else if(segment.length){segments.push(segment);segment=[]}}if(segment.length)segments.push(segment);for(const segment of segments)out+=\'<polyline fill="none" stroke="#197a91" stroke-width="3" points="\'+segment.map(p=>x(p.horizon_sessions)+\',\'+y(p[key])).join(\' \')+\'"/>\';for(const h of [0,5,10,15,20])out+=\'<text x="\'+x(h)+\'" y="\'+(H-24)+\'" text-anchor="middle">\'+h+\'</text>\';return out+\'<text x="\'+W/2+\'" y="\'+(H-4)+\'" text-anchor="middle">Trading sessions after entry close</text></svg>\'}el(\'run\').textContent=D.run_id;el(\'context\').textContent=\'Historical corpus: \'+num(D.historical_documents)+\' article identities. Reused saved query cohort: \'+num(D.query_documents)+\'. Article bodies were not fetched.\';const P=D.performance||{};const elapsed=P.processing_active_seconds??P.processing_seconds??P.active_invocation_seconds??P.elapsed_seconds;const rate=P.documents_per_processing_second??null;el(\'cards\').innerHTML=cards([[\'Saved query articles\',num(P.completed_query_documents??P.completed_query_articles)],[\'Measured retrieval seconds\',num(elapsed)],[\'Saved queries / second\',num(rate)]]);el(\'scope\').textContent=P.scope||\'See the recorded stage and job timing scopes. This report snapshot precedes its own BigQuery materialization and final verification.\';const stages=P.stages||P.stage_timings||[],maxStage=Math.max(1,...stages.map(s=>s.elapsed_seconds||0));el(\'stages\').innerHTML=stages.map(s=>\'<div class="stage"><code>\'+esc(s.phase)+\'</code><span class="bar" style="width:\'+100*(s.elapsed_seconds||0)/maxStage+\'%"></span><small>\'+num(s.elapsed_seconds)+\' s</small></div>\').join(\'\')||\'<p>No completed stage timings were available at this snapshot.</p>\';const jobs=P.jobs||P.server_job_timings||[];el(\'jobs\').innerHTML=jobs.length?\'<table><thead><tr><th>Operation</th><th>Queue seconds</th><th>Server seconds</th><th>Slot-ms</th><th>Bytes billed</th></tr></thead><tbody>\'+jobs.map(j=>\'<tr><td>\'+esc(j.key||j.operation||j.phase||j.job_id)+\'</td><td>\'+num(j.queue_seconds)+\'</td><td>\'+num(j.execution_seconds??j.server_execution_seconds)+\'</td><td>\'+num(j.total_slot_ms??j.totalSlotMs)+\'</td><td>\'+num(j.total_bytes_billed??j.totalBytesBilled)+\'</td></tr>\').join(\'\')+\'</tbody></table>\':\'<p>Server-job detail is present only when measured in the saved receipt.</p>\';el(\'capacity\').textContent=P.capacity_note||\'This controlled comparison excludes fresh intake and embedding work. A later live-feed test must measure arrivals, filtering, new embeddings, retrieval, queue growth and failures before claiming sustainable headroom.\';const entries=Object.entries(P).filter(([k,v])=>![\'scope\',\'stages\',\'stage_timings\',\'jobs\',\'server_job_timings\',\'capacity_note\'].includes(k)&&v!==null&&typeof v!==\'object\');el(\'accounting\').innerHTML=\'<table><tbody>\'+entries.map(([k,v])=>\'<tr><th>\'+esc(k.replaceAll(\'_\',\' \'))+\'</th><td>\'+esc(v)+\'</td></tr>\').join(\'\')+\'</tbody></table>\';el(\'performance-json\').textContent=JSON.stringify(P,null,2);const childRows=Array.isArray(P.child_statement_timings)?P.child_statement_timings.filter(j=>j&&typeof j===\'object\'&&!Array.isArray(j)):[];const childSeconds=j=>typeof j.execution_seconds===\'number\'&&Number.isFinite(j.execution_seconds)&&j.execution_seconds>=0?j.execution_seconds:null;const childName=j=>typeof j.destination?.tableId===\'string\'&&j.destination.tableId?j.destination.tableId:(typeof j.statement_type===\'string\'&&j.statement_type?j.statement_type:\'Unlabeled statement\');childRows.sort((a,b)=>(childSeconds(b)??-1)-(childSeconds(a)??-1));const longest=childRows.find(j=>childSeconds(j)!==null);el(\'child-summary\').textContent=longest?\'Largest measured child statement: \'+childName(longest)+\' — \'+num(childSeconds(longest))+\' server seconds. Parent stage: \'+(longest.key||\'Unavailable\')+\'. Compare this statement with the grouped stage timings above when assessing the full pipeline.\':\'No measured child-statement execution time is available in this snapshot.\';el(\'child-jobs\').innerHTML=childRows.length?\'<table><thead><tr><th>Stage / parent job</th><th>Statement or output table</th><th>Server seconds</th><th>Slot-ms</th><th>Bytes billed</th></tr></thead><tbody>\'+childRows.map(j=>\'<tr><td>\'+esc(j.key||\'Unavailable\')+\'<br><small><code>\'+esc(j.parent_job_id||\'Parent identifier unavailable\')+\'</code></small></td><td><code>\'+esc(childName(j))+\'</code></td><td>\'+num(childSeconds(j))+\'</td><td>\'+num(j.total_slot_ms)+\'</td><td>\'+num(j.total_bytes_billed)+\'</td></tr>\').join(\'\')+\'</tbody></table>\':\'<p>No child-statement metadata was available at this snapshot.</p>\';const A=P.accuracy||{};el(\'quality-cards\').innerHTML=cards([[\'Sampled recall at 20\',pct(A.mean_recall_at_20)],[\'Sampled top-1 identity agreement\',pct(A.top1_identity_agreement_rate)],[\'Sampled top-1 distance agreement\',pct(A.top1_distance_agreement_rate)]]);el(\'quality-scope\').textContent=\'Exact-reference comparison covers \'+num(A.sample_unique_requests??A.query_documents)+\' deterministic representatives with distinct embedding inputs, drawn from \'+num(D.query_documents)+\' saved query articles. All of those articles receive approximate cosine, BM25 and combined matching. The exact-reference sample is separate diagnostic work and does not establish full-cohort exact recall.\';el(\'index-evidence\').textContent=\'Recorded vector-index usage: \'+(typeof P.index_use_mode===\'string\'?P.index_use_mode:\'See the saved query-plan evidence\')+\'.\';</script></body></html>')
         ELSE NULL
     END AS html_text
   FROM payloads AS p)
SELECT
  @run_id AS run_id,
  r.report_name AS report_name,
  r.page_number AS page_number,
  r.html_text AS html_text,
  LOWER(TO_HEX(SHA256(r.html_text))) AS html_sha256,
  BYTE_LENGTH(r.html_text) AS html_bytes,
  CURRENT_TIMESTAMP() AS created_at
FROM rendered AS r;
